const mkList = (b) => b.map(a => a.slug + ':\n' + a.venues.map(v => '  #' + v.rank + ' ' + v.name + ' - ' + (v.area || '')).join('\n')).join('\n\n');
const res = await parallel(BATCHES.map((b, bi) => () =>
  agent('ตรวจสอบว่าร้านอาหาร/คาเฟ่ที่จัดอันดับไว้ยังเปิดอยู่จริงไหม (QA) - ตรวจอย่างเดียว ห้ามแก้ไฟล์. บทความ eat-ranking ต่างจังหวัด.\n' +
    'แต่ละร้าน: web-search ชื่อ+จังหวัด/พื้นที่ แล้วประเมิน open = ยังเปิดดำเนินการ (ปิดถาวร/ย้าย/เปลี่ยนชื่อถาวร = false). ปิด/ย้าย/เปลี่ยนชื่อ ให้ใส่ issue สั้นๆ + severity. เปิดปกติ open=true severity=none. อย่าเดา ถ้าไม่ชัวร์ให้ค้นจริง; ร้านเล็ก/สตรีทฟู้ด/ร้านท้องถิ่นที่หาไม่เจอแต่ไม่มีสัญญาณปิด ให้ open=true severity=none.\n\n' +
    mkList(b) + '\n\nreturn: articles[] (1 ต่อ slug ครบทุก slug; venues[] 1 ต่อร้านครบทุกร้าน)',
    { label: 'venues:' + b[0].cluster + '#' + (bi + 1), phase: 'Verify', schema: SCH })
    .then(r => r?.articles || []).catch(e => [{ slug: '__err' + bi, venues: [{ name: 'batch', open: true, issue: String(e), severity: 'none' }] }])
))
return { articles: res.flat() }
